from lib import *
S = SS('x39')
steps = [
    step("DispatcherServlet 背后的组件(Spring Boot 自动配置好之后)。DispatcherServlet 本身是容器里的一个 Bean。HandlerMapping 按顺序是 RouterFunctionMapping、RequestMappingHandlerMapping、WelcomePageHandlerMapping、BeanNameUrlHandlerMapping、WelcomePageNotAcceptableHandlerMapping、SimpleUrlHandlerMapping。HandlerAdapter 按顺序是 RequestMappingHandlerAdapter、HandlerFunctionAdapter、HttpRequestHandlerAdapter、SimpleControllerHandlerAdapter。RequestMappingHandlerAdapter 有 29 个参数解析器、15 个返回值处理器、6 个消息转换器(ByteArray、String、Resource、ResourceRegion、AllEncompassingForm、JacksonJson)。RequestMappingHandlerMapping 登记了 5 个处理方法:两个 /error、GET /boom、GET /hello/{name}、POST /only-post。", t=tl(S(1)), mark=lidx(S(1), 'RequestMappingHandlerAdapter 的参数解析器'), done=lidx(S(1), 'HandlerMapping(按顺序)', 'HandlerAdapter(按顺序)', 'RequestMappingHandlerMapping 登记'), b=bars([['HandlerMapping 个数', 6, '6'], ['HandlerAdapter 个数', 4, '4'], ['参数解析器个数', 29, '29'], ['返回值处理器个数', 15, '15'], ['消息转换器个数', 6, '6']], 29, done=[0, 1], cur=[2, 3, 4]), kv=KV([['HandlerMapping', '6 个,请求去哪个处理器'], ['HandlerAdapter', '4 个,怎么调用处理器'], ['参数解析器', '29 个'], ['消息转换器', '6 个']], ['HandlerMapping'])),
    step("一个成功请求 GET /hello/spring 经过的环节:Filter 进入(第一个记录),Interceptor.preHandle(handler 类型是 HandlerMethod,方法 hello),自定义 HandlerMethodArgumentResolver 解析 Trace 参数,Controller 方法 hello(spring, Trace[id=t-1]) 执行,ResponseBodyAdvice.beforeBodyWrite(将用 JacksonJsonHttpMessageConverter 写出),Interceptor.postHandle,Interceptor.afterCompletion(异常无),Filter 返回(状态码 200)。响应是 200 {\"hi\":\"spring\"}。中间的 HandlerMapping 查找和 HandlerAdapter 选择没有对外的回调,所以没有记录。", t=tl(S(2)), mark=lidx(S(2), 'Controller 方法 hello'), done=lidx(S(2), 'Filter 进入 GET /hello/spring', 'Interceptor.preHandle', '自定义 HandlerMethodArgumentResolver', 'beforeBodyWrite', 'Interceptor.postHandle', 'Interceptor.afterCompletion', 'Filter 返回'), b=bars([['被记录的环节个数', 8, '8'], ['Controller 方法执行次数', 1, '1']], 8, done=[0], mark=[1]), kv=KV([['外层', 'Filter 进入与返回'], ['拦截器', 'preHandle → … → postHandle → afterCompletion'], ['参数与返回值', '参数解析器、ResponseBodyAdvice、消息转换器'], ['响应', '200 {"hi":"spring"}']], ['拦截器'])),
    step("控制器里抛异常的请求 GET /boom(有一个 @ExceptionHandler)。Filter 进入,Interceptor.preHandle(handler 是 HandlerMethod(boom)),控制器抛 IllegalStateException,@ExceptionHandler 处理它,返回 500 handled;随后 ResponseBodyAdvice.beforeBodyWrite(用 StringHttpMessageConverter 写出),Interceptor.afterCompletion 的异常参数是“无”(异常已经被处理掉了),没有 postHandle,Filter 返回状态码 500。", t=tl(S(3)), mark=lidx(S(3), '@ExceptionHandler 处理 IllegalStateException'), done=lidx(S(3), 'Filter 进入 GET /boom', 'Interceptor.preHandle', 'beforeBodyWrite', 'Interceptor.afterCompletion', 'Filter 返回'), b=bars([['postHandle 被调用', 0, '0(异常路径没有)'], ['afterCompletion 被调用', 1, '1(异常参数为无)'], ['@ExceptionHandler 被调用', 1, '1']], 1, mark=[0], done=[1, 2]), kv=KV([['抛异常的路径', '没有 postHandle'], ['afterCompletion', '照常调用,异常参数为空(已被处理)'], ['异常处理', '@ExceptionHandler 返回 500'], ['响应写出', '仍然经过 ResponseBodyAdvice']], ['抛异常的路径'])),
    step("没有匹配的处理器。GET /nope(404):Filter 进入,Interceptor.preHandle 被调用,handler 是 ResourceHttpRequestHandler(静态资源处理器兜底),afterCompletion,Filter 返回 404;随后 Servlet 容器把请求转到 /error(错误派发):Interceptor.preHandle 的 handler 变成 HandlerMethod(error),ResponseBodyAdvice、postHandle、afterCompletion 又走一遍,Filter 没有再进入(OncePerRequestFilter 不处理错误派发)。GET /only-post(路径对、方法不对,405):Filter 进入,没有调用 Interceptor.preHandle(没有找到处理器,直接由异常解析器 405),Filter 返回 405,然后 /error 的派发。", t=tl(S(4)), mark=lidx(S(4), 'GET /nope', 'GET /only-post'), b=bars([['404 路径里 preHandle 被调用次数', 2, '2(静态资源处理器与 /error)'], ['405 路径里第一遍 preHandle 被调用', 0, '0'], ['错误派发里 Filter 进入次数', 0, '0']], 2, cur=[0], mark=[1, 2]), kv=KV([['404', '静态资源处理器兜底,preHandle 被调用,再转 /error'], ['405', '没有处理器,preHandle 不调用,异常解析器处理'], ['/error 派发', '拦截器再来一遍,OncePerRequestFilter 跳过'], ['所以', '拦截器里的日志会因为错误派发出现两次']], ['所以'])),
]
A = mkartx('x39', 39, 'Spring,MVC,DispatcherServlet,请求处理,拦截器,真实验证,动画演示',
    '实测一个请求在 Spring MVC 里的完整路径:Filter → Interceptor.preHandle → 参数解析器 → Controller → ResponseBodyAdvice/消息转换器 → postHandle → afterCompletion → Filter;抛异常时没有 postHandle,由 @ExceptionHandler 处理;404 由静态资源处理器兜底再转 /error,405 不调用 preHandle;Boot 里有 6 个 HandlerMapping、4 个 HandlerAdapter、29 个参数解析器。',
    '一个 HTTP 请求进到 Spring MVC 之后到底经过哪些环节?Filter、Interceptor、参数解析、返回值处理各在什么时候?抛异常和 404、405 又是怎么走的?这篇用 Spring Boot 4.0.8 的 Spring MVC 7.0.9,把每个扩展点的调用顺序逐个记下来。',
    [('29 个', 'RequestMappingHandlerAdapter 的参数解析器个数(返回值处理器 15 个,消息转换器 6 个)'), ('0 次', 'GET /only-post(405)在第一遍里 Interceptor.preHandle 被调用的次数'), ('ResourceHttpRequestHandler', 'GET /nope 的 404 实际上由静态资源处理器兜底处理')],
    [('组件', '<p>DispatcherServlet 背后有 6 个 HandlerMapping、4 个 HandlerAdapter 和一长串解析器。</p>'),
     ('成功路径', '<p>Filter 包住拦截器,拦截器包住控制器方法,返回值经过 ResponseBodyAdvice 和消息转换器写出。</p>'),
     ('异常路径', '<p>异常由 @ExceptionHandler 处理,没有 postHandle,afterCompletion 照常调用。</p>'),
     ('404 与 405', '<p>404 由静态资源处理器兜底再转 /error,405 没有处理器,拦截器在错误派发里再走一遍。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-webmvc,内嵌 Tomcat 11),事件由 Filter、HandlerInterceptor、HandlerMethodArgumentResolver、ResponseBodyAdvice、@ExceptionHandler 这些公开扩展点打印,所以 HandlerMapping 查找、HandlerAdapter 选择这些没有回调的环节在时间线里看不到',
     '没有验证:异步请求(DeferredResult / Callable)的 Interceptor 调用次数(见后面的异步请求篇);multipart 请求;ViewResolver 与模板引擎路径(这里只测了 @RestController);HandlerMapping 的 Order 值本身;WebMvcConfigurer 之外直接重写 DispatcherServlet 的做法'],
    'DispatcherServlet 的请求路径')
